//! ICU break dictionaries for Thai, Lao, Khmer, Burmese, and CJK word
//! segmentation.
//!
//! The blob is generated by tools/unicode/break/generate_dictionaries.py from
//! the ICU break dictionaries. Each dictionary is a compact byte trie: a node
//! stores its edge range and word cost, and edges pack the byte and child
//! index. Wide nodes use a 256-bit bitmap with compact child indices instead of
//! sorted edges. A single walk per text position replaces the per-prefix binary
//! searches, and the CJK entries carry the ICU unigram costs used by the
//! Viterbi segmenter.

const std = @import("std");
const properties = @import("../properties.zig");
const script = @import("../script/root.zig");

const data = @embedFile("dictionaries.bin");

pub const Language = enum(u8) { thai = 0, lao = 1, khmer = 2, burmese = 3, cjk = 4 };

const language_count = 5;
const header_len = 8;
const record_len = 12;
const node_len = 8;
const edge_len = 4;
const bitmap_threshold = 16;
pub const max_run_codepoints = 256;
const cjk_fallback_cost: u32 = 255;
const cjk_max_word_codepoints = 16;

pub const Match = struct {
    byte_len: usize,
    cp_len: usize,
    cost: u16,
};

const LanguageData = struct {
    node_count: usize,
    max_word_bytes: usize,
    nodes_offset: usize,
    edges_offset: usize,
};

const layout = blk: {
    var languages: [language_count]LanguageData = undefined;
    var cursor: usize = header_len + language_count * record_len;
    for (0..language_count) |index| {
        const record = header_len + index * record_len;
        const node_count: usize = @intCast(readU32(record));
        const edge_count: usize = @intCast(readU32(record + 4));
        const max_word_bytes: usize = @intCast(readU16(record + 8));
        languages[index] = .{
            .node_count = node_count,
            .max_word_bytes = max_word_bytes,
            .nodes_offset = cursor,
            .edges_offset = cursor + node_count * node_len,
        };
        cursor += node_count * node_len + edge_count * edge_len;
    }
    break :blk .{ .languages = languages, .total = cursor };
};

comptime {
    if (data.len < header_len or !std.mem.eql(u8, data[0..4], "CJDB") or
        data[4] != 3 or data[5] != language_count)
    {
        @compileError("invalid break dictionary data");
    }
    if (layout.total != data.len) {
        @compileError("invalid break dictionary data lengths");
    }
}

fn readU16(offset: usize) u16 {
    return std.mem.readInt(u16, data[offset..][0..2], .little);
}

fn readU32(offset: usize) u32 {
    return std.mem.readInt(u32, data[offset..][0..4], .little);
}

fn readU64(offset: usize) u64 {
    return std.mem.readInt(u64, data[offset..][0..8], .little);
}

fn languageData(language: Language) LanguageData {
    return layout.languages[@as(usize, @intFromEnum(language))];
}

const Node = struct {
    edge_start: usize,
    edge_count: usize,
    cost_plus_one: u16,
};

/// A language's trie with its offsets hoisted out of the hot walk loops.
const Trie = struct {
    nodes_offset: usize,
    edges_offset: usize,
    max_word_bytes: usize,

    fn node(self: Trie, index: usize) Node {
        const base = self.nodes_offset + index * node_len;
        const word = std.mem.readInt(u64, data[base..][0..8], .little);
        return .{
            .edge_start = @intCast(word & 0xffff_ffff),
            .edge_count = @intCast((word >> 32) & 0xffff),
            .cost_plus_one = @intCast(word >> 48),
        };
    }

    fn edge(self: Trie, index: usize) u32 {
        return readU32(self.edges_offset + index * edge_len);
    }

    /// Follow one trie edge. Edges are sorted by byte; small nodes use a
    /// linear scan, and high-fan-out nodes use a 256-bit bitmap plus popcount,
    /// which beats binary search on the wide second-byte nodes.
    fn child(self: Trie, node_index: usize, byte: u8) ?usize {
        const current = self.node(node_index);
        const count = current.edge_count;
        if (count == 0) return null;
        if (count <= 8) {
            var index: usize = 0;
            while (index < count) : (index += 1) {
                const entry = self.edge(current.edge_start + index);
                const entry_byte: u8 = @intCast(entry >> 24);
                if (entry_byte == byte) return @intCast(entry & 0x00ff_ffff);
                if (entry_byte > byte) return null;
            }
            return null;
        }
        if (count <= bitmap_threshold) {
            var low: usize = 0;
            var high: usize = count;
            while (low < high) {
                const middle = low + (high - low) / 2;
                const entry = self.edge(current.edge_start + middle);
                if (@as(u8, @intCast(entry >> 24)) < byte) {
                    low = middle + 1;
                } else {
                    high = middle;
                }
            }
            if (low >= count) return null;
            const entry = self.edge(current.edge_start + low);
            if (@as(u8, @intCast(entry >> 24)) != byte) return null;
            return @intCast(entry & 0x00ff_ffff);
        }

        const bitmap_offset = self.edges_offset + current.edge_start * edge_len;
        const word_index: usize = byte >> 6;
        const bit: u64 = @as(u64, 1) << @as(u6, @intCast(byte & 63));
        const word = readU64(bitmap_offset + word_index * 8);
        if (word & bit == 0) return null;
        var index: usize = 0;
        var previous: usize = 0;
        while (previous < word_index) : (previous += 1) {
            index += @as(usize, @popCount(readU64(bitmap_offset + previous * 8)));
        }
        index += @as(usize, @popCount(word & (bit - 1)));
        const entry = self.edge(current.edge_start + 8 + index);
        return @intCast(entry & 0x00ff_ffff);
    }
};

fn trie(language: Language) Trie {
    const info = languageData(language);
    return .{
        .nodes_offset = info.nodes_offset,
        .edges_offset = info.edges_offset,
        .max_word_bytes = info.max_word_bytes,
    };
}

/// Exact dictionary lookup for a UTF-8 word slice.
pub fn findExact(language: Language, word: []const u8) ?u16 {
    if (word.len == 0) return null;
    const table = trie(language);
    if (word.len > table.max_word_bytes) return null;
    var node_index: usize = 0;
    for (word) |byte| {
        node_index = table.child(node_index, byte) orelse return null;
    }
    const cost_plus_one = table.node(node_index).cost_plus_one;
    if (cost_plus_one == 0) return null;
    return cost_plus_one - 1;
}

/// Longest dictionary word starting at `start` and ending at or before `end`.
pub fn longestMatch(
    language: Language,
    text: []const u8,
    start: usize,
    end: usize,
) ?Match {
    const limit = @min(end, text.len);
    if (start >= limit) return null;
    const table = trie(language);
    const byte_limit = @min(limit - start, table.max_word_bytes);

    var node_index: usize = 0;
    var best: ?Match = null;
    var codepoints: usize = 0;
    var offset: usize = 0;
    while (offset < byte_limit) : (offset += 1) {
        const byte = text[start + offset];
        node_index = table.child(node_index, byte) orelse break;
        if ((byte & 0xc0) != 0x80) codepoints += 1;
        const cost_plus_one = table.node(node_index).cost_plus_one;
        if (cost_plus_one != 0) {
            best = .{
                .byte_len = offset + 1,
                .cp_len = codepoints,
                .cost = cost_plus_one - 1,
            };
        }
    }
    return best;
}

/// Longest prefix of the text that is a prefix of some dictionary word.
pub fn longestPrefix(
    language: Language,
    text: []const u8,
    start: usize,
    end: usize,
) usize {
    const limit = @min(end, text.len);
    if (start >= limit) return 0;
    const table = trie(language);
    const byte_limit = @min(limit - start, table.max_word_bytes);
    var node_index: usize = 0;
    var codepoints: usize = 0;
    var pending: usize = 0;
    var offset: usize = 0;
    while (offset < byte_limit) : (offset += 1) {
        const byte = text[start + offset];
        node_index = table.child(node_index, byte) orelse break;
        if (pending == 0) {
            pending = (std.unicode.utf8ByteSequenceLength(byte) catch 1) - 1;
            if (pending == 0) codepoints += 1;
        } else {
            pending -= 1;
            if (pending == 0) codepoints += 1;
        }
    }
    return codepoints;
}

fn decode(text: []const u8, offset: usize) ?struct {
    codepoint: u21,
    next: usize,
} {
    if (offset >= text.len) return null;
    const length = std.unicode.utf8ByteSequenceLength(text[offset]) catch return null;
    if (offset + length > text.len) return null;
    const codepoint = std.unicode.utf8Decode(text[offset..][0..length]) catch return null;
    return .{ .codepoint = codepoint, .next = offset + length };
}

fn isMark(codepoint: u21) bool {
    return switch (properties.category(codepoint)) {
        .Mn, .Mc, .Me => true,
        else => false,
    };
}

pub fn languageForCodepoint(codepoint: u21) ?Language {
    return switch (script.forCodepoint(codepoint)) {
        .thai => .thai,
        .lao => .lao,
        .khmer => .khmer,
        .myanmar => .burmese,
        .han, .hiragana, .katakana => .cjk,
        else => switch (codepoint) {
            0x30fc, 0xff70, 0xff9e, 0xff9f => .cjk,
            else => null,
        },
    };
}

pub fn isRunCodepoint(language: Language, codepoint: u21) bool {
    if (isMark(codepoint)) return true;
    return languageForCodepoint(codepoint) == language;
}

/// All dictionary words starting at `start` and ending at or before `end`, in
/// increasing length order. A single trie walk replaces one lookup per prefix
/// length.
pub fn matchesAt(
    language: Language,
    text: []const u8,
    start: usize,
    end: usize,
    byte_lengths: []usize,
    cp_lengths: []usize,
    costs: []u16,
) usize {
    const limit = @min(end, text.len);
    if (start >= limit) return 0;
    const table = trie(language);
    const byte_limit = @min(limit - start, table.max_word_bytes);
    var node_index: usize = 0;
    var count: usize = 0;
    var codepoints: usize = 0;
    var offset: usize = 0;
    while (offset < byte_limit) : (offset += 1) {
        const byte = text[start + offset];
        node_index = table.child(node_index, byte) orelse break;
        if ((byte & 0xc0) != 0x80) codepoints += 1;
        const cost_plus_one = table.node(node_index).cost_plus_one;
        if (cost_plus_one != 0) {
            if (count == byte_lengths.len) break;
            byte_lengths[count] = offset + 1;
            cp_lengths[count] = codepoints;
            costs[count] = cost_plus_one - 1;
            count += 1;
        }
    }
    return count;
}

const possible_word_count = 20;

/// ICU's PossibleWord: the dictionary candidates at one text position, in
/// increasing length order, with the longest-prefix lookahead used by the
/// Thai/Lao/Khmer/Burmese resynchronization heuristic.
const PossibleWord = struct {
    offset: usize = std.math.maxInt(usize),
    byte_lengths: [possible_word_count]usize = undefined,
    cp_lengths: [possible_word_count]usize = undefined,
    costs: [possible_word_count]u16 = undefined,
    count: usize = 0,
    prefix: usize = 0,
    mark: usize = 0,
    current: usize = 0,

    fn candidates(
        self: *PossibleWord,
        language: Language,
        text: []const u8,
        start: usize,
        end: usize,
    ) usize {
        if (start != self.offset) {
            self.offset = start;
            self.count = matchesAt(
                language,
                text,
                start,
                end,
                &self.byte_lengths,
                &self.cp_lengths,
                &self.costs,
            );
            self.prefix = longestPrefix(language, text, start, end);
        }
        if (self.count > 0) {
            self.current = self.count - 1;
        } else {
            self.current = 0;
        }
        self.mark = self.current;
        return self.count;
    }

    fn currentPosition(self: *const PossibleWord) usize {
        return self.offset +
            (if (self.count > 0) self.byte_lengths[self.current] else 0);
    }

    fn acceptMarked(self: *const PossibleWord) usize {
        return self.offset + self.byte_lengths[self.mark];
    }

    fn markedCpLength(self: *const PossibleWord) usize {
        return self.cp_lengths[self.mark];
    }

    fn backUp(self: *PossibleWord) bool {
        if (self.current > 0) {
            self.current -= 1;
            return true;
        }
        return false;
    }

    fn markCurrent(self: *PossibleWord) void {
        self.mark = self.current;
    }
};

fn isEndWord(language: Language, codepoint: u21) bool {
    if (!isRunCodepoint(language, codepoint)) return false;
    return switch (language) {
        .thai => codepoint != 0x0e31 and
            !(codepoint >= 0x0e40 and codepoint <= 0x0e44),
        .lao => !(codepoint >= 0x0ec0 and codepoint <= 0x0ec4),
        .khmer => codepoint != 0x17d2,
        .burmese, .cjk => true,
    };
}

fn isBeginWord(language: Language, codepoint: u21) bool {
    return switch (language) {
        .thai => (codepoint >= 0x0e01 and codepoint <= 0x0e2e) or
            (codepoint >= 0x0e40 and codepoint <= 0x0e44),
        .lao => (codepoint >= 0x0e81 and codepoint <= 0x0eae) or
            (codepoint >= 0x0edc and codepoint <= 0x0edd) or
            (codepoint >= 0x0ec0 and codepoint <= 0x0ec4),
        .khmer => codepoint >= 0x1780 and codepoint <= 0x17b3,
        .burmese => codepoint >= 0x1000 and codepoint <= 0x102a,
        .cjk => true,
    };
}

fn isSuffix(language: Language, codepoint: u21) bool {
    return language == .thai and
        (codepoint == 0x0e2f or codepoint == 0x0e46);
}

fn previousCodepoint(text: []const u8, position: usize) ?u21 {
    if (position == 0 or position > text.len) return null;
    var start = position - 1;
    while (start > 0 and (text[start] & 0xc0) == 0x80) start -= 1;
    const decoded = decode(text, start) orelse return null;
    if (decoded.next != position) return null;
    return decoded.codepoint;
}

/// Segment a Thai/Lao/Khmer/Burmese run with ICU's candidate lookahead.
/// Internal breaks are byte offsets after each word; the run end is included
/// only when the last word reaches it.
pub fn segmentSoutheastAsian(
    language: Language,
    text: []const u8,
    start: usize,
    end: usize,
    breaks: []usize,
) usize {
    if (end <= start) return 0;

    // MIN_WORD_SPAN: fewer than four scalars cannot hold two minimum words.
    var span = start;
    var span_codepoints: usize = 0;
    while (span < end and span_codepoints < 4) {
        const decoded = decode(text, span) orelse break;
        span = decoded.next;
        span_codepoints += 1;
    }
    if (span_codepoints < 4 or span >= end) return 0;

    var words: [3]PossibleWord = .{ .{}, .{}, .{} };
    var words_found: usize = 0;
    var position = start;
    var count: usize = 0;

    while (position < end) {
        const current = position;
        var cp_word_length: usize = 0;
        var word_length: usize = 0;
        const slot = words_found % 3;
        const candidates = words[slot].candidates(
            language,
            text,
            position,
            end,
        );
        if (candidates == 1) {
            word_length = words[slot].acceptMarked() - current;
            cp_word_length = words[slot].markedCpLength();
            position = current + word_length;
            words_found += 1;
        } else if (candidates > 1) {
            position = words[slot].currentPosition();
            if (position < end) {
                var found_best = false;
                while (true) {
                    const next_slot = (words_found + 1) % 3;
                    if (words[next_slot].candidates(
                        language,
                        text,
                        position,
                        end,
                    ) > 0) {
                        words[slot].markCurrent();
                        position = words[next_slot].currentPosition();
                        if (position >= end) {
                            found_best = true;
                            break;
                        }
                        while (true) {
                            const third_slot = (words_found + 2) % 3;
                            if (words[third_slot].candidates(
                                language,
                                text,
                                position,
                                end,
                            ) > 0) {
                                words[slot].markCurrent();
                                found_best = true;
                                break;
                            }
                            if (!words[next_slot].backUp()) break;
                            position = words[next_slot].currentPosition();
                        }
                        if (found_best) break;
                    }
                    if (!words[slot].backUp()) break;
                    position = words[slot].currentPosition();
                }
            }
            word_length = words[slot].acceptMarked() - current;
            cp_word_length = words[slot].markedCpLength();
            position = current + word_length;
            words_found += 1;
        }

        // Combine a non-word with the preceding word, or scan forward to the
        // next plausible word start.
        if (position < end and cp_word_length < 3) {
            const prefix_candidates = words[words_found % 3].candidates(
                language,
                text,
                position,
                end,
            );
            if (prefix_candidates <= 0 and
                (word_length == 0 or words[words_found % 3].prefix < 3))
            {
                var remaining = end - (current + word_length);
                var chars: usize = 0;
                while (true) {
                    const before = position;
                    const decoded = decode(text, position) orelse break;
                    position = decoded.next;
                    chars += decoded.next - before;
                    remaining -= decoded.next - before;
                    if (remaining <= 0) break;
                    const next = decode(text, position) orelse break;
                    if (isEndWord(language, decoded.codepoint) and
                        isBeginWord(language, next.codepoint))
                    {
                        const resumed = words[(words_found + 1) % 3].candidates(
                            language,
                            text,
                            position,
                            end,
                        );
                        position = current + word_length + chars;
                        if (resumed > 0) break;
                    }
                }
                if (word_length == 0) words_found += 1;
                word_length += chars;
                position = current + word_length;
            } else {
                position = current + word_length;
            }
        }

        // Never stop before a combining mark.
        while (position < end) {
            const before = position;
            const decoded = decode(text, position) orelse break;
            if (!isMark(decoded.codepoint)) break;
            position = decoded.next;
            word_length += decoded.next - before;
        }

        // Thai elision and repetition marks attach to the preceding word
        // when they do not start a dictionary word themselves.
        if (position < end and word_length > 0) {
            const decoded = decode(text, position) orelse null;
            if (decoded != null and isSuffix(language, decoded.?.codepoint) and
                longestMatch(language, text, position, end) == null)
            {
                const previous = previousCodepoint(text, position);
                if (previous == null or !isSuffix(language, previous.?)) {
                    word_length += decoded.?.next - position;
                    position = current + word_length;
                }
            }
        }

        if (word_length > 0) {
            if (count == breaks.len) return count;
            breaks[count] = current + word_length;
            count += 1;
            position = current + word_length;
        }
    }
    return count;
}

fn codepointAt(text: []const u8, offset: usize) u21 {
    const decoded = decode(text, offset) orelse return 0;
    return decoded.codepoint;
}

fn isKatakana(codepoint: u21) bool {
    return (codepoint >= 0x30a1 and codepoint <= 0x30fe and
        codepoint != 0x30fb) or
        (codepoint >= 0xff66 and codepoint <= 0xff9f);
}

fn katakanaCost(length: usize) u32 {
    const costs = [_]u32{ 8192, 984, 408, 240, 204, 252, 300, 372, 480 };
    return if (length >= costs.len) 8192 else costs[length];
}

/// Segment a CJK run with the ICU-style Viterbi search over dictionary costs.
pub fn segmentCjk(
    text: []const u8,
    start: usize,
    end: usize,
    breaks: []usize,
) usize {
    var offsets: [max_run_codepoints + 1]usize = undefined;
    offsets[0] = start;
    var codepoint_count: usize = 0;
    var cursor = start;
    while (cursor < end and codepoint_count < max_run_codepoints) {
        const decoded = decode(text, cursor) orelse break;
        cursor = decoded.next;
        codepoint_count += 1;
        offsets[codepoint_count] = cursor;
    }
    if (codepoint_count == 0) return 0;
    const limit = offsets[codepoint_count];

    var best: [max_run_codepoints + 1]u32 = undefined;
    var prev: [max_run_codepoints + 1]u32 = undefined;
    for (0..codepoint_count + 1) |index| {
        best[index] = std.math.maxInt(u32);
        prev[index] = 0;
    }
    best[0] = 0;

    var previous_katakana = false;
    var byte_lengths: [cjk_max_word_codepoints]usize = undefined;
    var cp_lengths: [cjk_max_word_codepoints]usize = undefined;
    var costs: [cjk_max_word_codepoints]u16 = undefined;
    for (0..codepoint_count) |index| {
        if (best[index] == std.math.maxInt(u32)) continue;
        var single_match = false;
        const max_length = @min(
            cjk_max_word_codepoints,
            codepoint_count - index,
        );
        const matches = matchesAt(
            .cjk,
            text,
            offsets[index],
            limit,
            &byte_lengths,
            &cp_lengths,
            &costs,
        );
        for (0..matches) |match_index| {
            const length = cp_lengths[match_index];
            if (length > max_length) continue;
            if (length == 1) single_match = true;
            const candidate = best[index] + @as(u32, costs[match_index]);
            const target = index + length;
            if (candidate < best[target]) {
                best[target] = candidate;
                prev[target] = @intCast(index);
            }
        }
        if (!single_match) {
            const candidate = best[index] + cjk_fallback_cost;
            if (candidate < best[index + 1]) {
                best[index + 1] = candidate;
                prev[index + 1] = @intCast(index);
            }
        }

        // ICU treats a continuous Katakana run as one candidate word with a
        // length-based default cost, which prevents single-kana over-splitting.
        const katakana = isKatakana(codepointAt(text, offsets[index]));
        if (!previous_katakana and katakana) {
            var run: usize = 1;
            while (index + run < codepoint_count and run < 20 and
                isKatakana(codepointAt(text, offsets[index + run])))
            {
                run += 1;
            }
            if (run < 20) {
                const candidate = best[index] + katakanaCost(run);
                const target = index + run;
                if (candidate < best[target]) {
                    best[target] = candidate;
                    prev[target] = @intCast(index);
                }
            }
        }
        previous_katakana = katakana;
    }

    var reverse: [max_run_codepoints + 1]usize = undefined;
    var reverse_count: usize = 0;
    var position = codepoint_count;
    while (position > 0) {
        reverse[reverse_count] = position;
        reverse_count += 1;
        position = prev[position];
    }
    var count: usize = 0;
    while (reverse_count > 0) {
        reverse_count -= 1;
        const boundary = offsets[reverse[reverse_count]];
        if (boundary == start) continue;
        if (count == breaks.len) break;
        breaks[count] = boundary;
        count += 1;
    }
    if (count == 0 or breaks[count - 1] != limit) {
        if (count < breaks.len) {
            breaks[count] = limit;
            count += 1;
        }
    }
    return count;
}

test "dictionary lookups" {
    const testing = @import("std").testing;
    try testing.expect(findExact(.thai, "ภาษา") != null);
    try testing.expect(findExact(.thai, "ไทย") != null);
    try testing.expect(findExact(.lao, "ພາສາ") != null);
    try testing.expect(findExact(.khmer, "ខ្មែរ") != null);
    try testing.expect(findExact(.burmese, "မြန်မာ") != null);
    try testing.expect(findExact(.cjk, "中华") != null);
    try testing.expect(findExact(.cjk, "not-a-cjk-word") == null);
    try testing.expectEqual(@as(?Language, .thai), languageForCodepoint('ก'));
    try testing.expectEqual(@as(?Language, .cjk), languageForCodepoint(0x4e00));
    try testing.expectEqual(@as(?Language, null), languageForCodepoint('a'));
}

test "Southeast Asian dictionary segmentation" {
    const testing = @import("std").testing;
    var breaks: [max_run_codepoints + 1]usize = undefined;

    const thai = "ภาษาไทย";
    const thai_count = segmentSoutheastAsian(.thai, thai, 0, thai.len, &breaks);
    try testing.expectEqual(@as(usize, 2), thai_count);
    try testing.expectEqualStrings("ภาษา", thai[0..breaks[0]]);
    try testing.expectEqualStrings("ไทย", thai[breaks[0]..breaks[1]]);

    const lao = "ພາສາລາວ";
    const lao_count = segmentSoutheastAsian(.lao, lao, 0, lao.len, &breaks);
    try testing.expectEqual(@as(usize, 2), lao_count);
    try testing.expectEqualStrings("ພາສາ", lao[0..breaks[0]]);
    try testing.expectEqualStrings("ລາວ", lao[breaks[0]..breaks[1]]);
}

test "CJK Viterbi segmentation" {
    const testing = @import("std").testing;
    var breaks: [max_run_codepoints + 1]usize = undefined;

    const cases = [_]struct {
        text: []const u8,
        expected: []const []const u8,
    }{
        .{
            .text = "中华人民共和国",
            .expected = &.{ "中华", "人民", "共和国" },
        },
        .{ .text = "日本語", .expected = &.{"日本語"} },
        .{ .text = "東京都", .expected = &.{ "東京", "都" } },
        .{ .text = "重庆市", .expected = &.{ "重庆", "市" } },
    };
    for (cases) |case| {
        const count = segmentCjk(case.text, 0, case.text.len, &breaks);
        try testing.expectEqual(case.expected.len, count);
        var start: usize = 0;
        for (case.expected, 0..) |expected, index| {
            const end = breaks[index];
            try testing.expectEqualStrings(expected, case.text[start..end]);
            start = end;
        }
    }
}
